/*
 Problem: 115. Distinct Subsequences
 Language: cpp
 Runtime: 11 ms (80.62%)
 Memory: 8.8 MB (97.47%)
 Tags: String, Dynamic Programming
*/
class Solution {
public:
    int numDistinct(string s, string t) {
        int n = t.size();
        vector<unsigned> dp(n + 1);
        dp[0] = 1;

        for (const auto& c : s)
            for (int j = n; j; --j)
                if (c == t[j - 1])
                    dp[j] += dp[j - 1];

        return dp[n];
    }
};
